3	import { RepositoryIssue } from "@/domain/models/RepositoryIssue";
4	import { GetRepositoryIssues } from "@/domain/use-cases/GetRepositoryIssues";
5	import {
6	  HttpClientProtocol,
7	  HttpStatusCode,
8	} from "../protocols/http/HttpClientProtocol";
