10	interface RemoteRepositoryIssues {
11	  id: number;
12	  title: string;
13	  html_url: string;
14	  user: {
15	    login: string;
16	  };
17	}
18	export class RemoteGetRepositoryIssues implements GetRepositoryIssues {
19	  private readonly perPage = 30;
20	
21	  constructor(
22	    private readonly url: string,
23	    private readonly httpClient: HttpClientProtocol
24	  ) {}
25	
26	  async get(owner: string, repositoryName: string): Promise<RepositoryIssue[]> {
27	    const httpResult = await this.httpClient.request({
28	      method: "GET",
29	      url: `${this.url}/${owner}/${repositoryName}/issues?page=1&per_page=${this.perPage}`,
30	    });
31	
32	    switch (httpResult.statusCode) {
33	      case HttpStatusCode.ok:
34	        return this.adapt(httpResult.body as RemoteRepositoryIssues[]);
35	      case HttpStatusCode.notFound:
36	        throw new InvalidRepositoryError();
37	      default:
38	        throw new UnexpectedError();
39	    }
40	  }
41	
42	  async getPage(owner: string, repositoryName: string, page: number): Promise<{ issues: RepositoryIssue[]; hasMore: boolean }> {
43	    const httpResult = await this.httpClient.request({
44	      method: "GET",
45	      url: `${this.url}/${owner}/${repositoryName}/issues?page=${page}&per_page=${this.perPage}`,
46	    });
47	
48	    switch (httpResult.statusCode) {
49	      case HttpStatusCode.ok:
50	        const issues = this.adapt(httpResult.body as RemoteRepositoryIssues[]);
51	        const hasMore = issues.length === this.perPage;
52	        return { issues, hasMore };
53	      case HttpStatusCode.notFound:
54	        throw new InvalidRepositoryError();
55	      default:
56	        throw new UnexpectedError();
57	    }
58	  }
59	
60	  private adapt(httpResponse: RemoteRepositoryIssues[]): RepositoryIssue[] {
61	    return httpResponse.map((response) => ({
62	      id: response.id,
63	      title: response.title,
64	      createdBy: response.user.login,
65	      linkTo: response.html_url,
66	    }));
67	  }
68	}
